const runningCancellationFixtureSource=String.raw`import{readFileSync,writeFileSync,existsSync}from'node:fs';const input=JSON.parse(readFileSync(new URL('./running-cancel-input.json',import.meta.url),'utf8'));const{runStatelessPartition}=await import(input.subject);const controller=new AbortController(),timer=setInterval(()=>{if(existsSync('.local/hold-started'))controller.abort();},20);try{const value=await runStatelessPartition({repoRoot:input.repoRoot,partition:'source-native',signal:controller.signal});writeFileSync(input.output,JSON.stringify(value));}finally{clearInterval(timer);}`;
const cohortPartitionFixtureSource=String.raw`import{readFileSync,writeFileSync,existsSync}from'node:fs';const input=JSON.parse(readFileSync(new URL('./cohort-run-input.json',import.meta.url),'utf8'));const{runStatelessPartition}=await import(input.subject);const controller=new AbortController();let timer;if(process.env.CUEVO_COHORT_TEST_MODE==='hold')timer=setInterval(()=>{if(existsSync('.local/executed.jsonl'))controller.abort();},10);try{const result=await runStatelessPartition({repoRoot:input.repoRoot,partition:input.partition??'source-contracts',signal:controller.signal});writeFileSync('.local/result.json',JSON.stringify(result));process.exitCode=result.status==='PASSED'?0:1;}finally{clearInterval(timer);}`;
const fixedProducerFixtureSource=String.raw`import{readFileSync,writeFileSync,existsSync}from'node:fs';const input=JSON.parse(readFileSync(new URL('./cohort-run-input.json',import.meta.url),'utf8'));const{runFixedSourceCohortProducer}=await import(input.subject);const controller=new AbortController();let timer;if(process.env.CUEVO_COHORT_TEST_MODE==='hold')timer=setInterval(()=>{if(existsSync('.local/executed.jsonl'))controller.abort();},10);try{const result=await runFixedSourceCohortProducer({repoRoot:input.repoRoot,id:input.id,signal:controller.signal});writeFileSync('.local/physical-result.json',JSON.stringify(result));process.exitCode=result.status==='PASSED'?0:1;}finally{clearInterval(timer);}`;

const partitionFixtureHookSource=String.raw`import{readFileSync}from'node:fs';import{registerHooks}from'node:module';const fixtureDataUrl=new URL('./partition-fixture-data.json',import.meta.url).href;const fixture=JSON.parse(readFileSync(new URL(fixtureDataUrl),'utf8'));registerHooks({resolve(specifier,context,next){if(specifier==='cuevo:partition-fixture-data'&&(context.parentURL===fixture.stepsUrl||context.parentURL===fixture.coverageUrl))return{url:fixtureDataUrl,shortCircuit:true};return next(specifier,context);},load(url,context,next){if(url===fixture.stepsUrl)return{format:'module',shortCircuit:true,source:"import fixture from 'cuevo:partition-fixture-data' with {type:'json'};export const statelessVerificationSteps=fixture.steps;"};if(url===fixture.coverageUrl)return{format:'module',shortCircuit:true,source:"import fixture from 'cuevo:partition-fixture-data' with {type:'json'};const coverage=fixture.coverage;export const readCiPartitionCoverage=()=>coverage;export const ciPartitionFiles=(_value,_scope,id)=>coverage.source.find(row=>row.id===id).files;export const ciPartitionFileSelections=(_value,requests)=>requests.map(row=>coverage.source.find(part=>part.id===row.id).files);"};return next(url,context);}});`;
const scratchOutcomeFixtureSource=String.raw`import fs from'node:fs/promises';import{syncBuiltinESMExports}from'node:module';const original={mkdtemp:fs.mkdtemp,chmod:fs.chmod,rm:fs.rm};let allocated=null,removals=0;globalThis.scratchOutcome=()=>({allocated,removals});fs.mkdtemp=async(...args)=>{if(process.env.CUEVO_SCRATCH_MODE==='allocate-refuse')throw Error('private-scratch-canary');const result=await original.mkdtemp(...args);allocated=result;return result;};fs.chmod=async(path,...args)=>{if(path===allocated)throw Error('private-scratch-canary');return original.chmod(path,...args);};fs.rm=async(path,...args)=>{if(path===allocated){removals++;if(process.env.CUEVO_SCRATCH_MODE==='remove-refuse')throw Error('private-scratch-canary');}return original.rm(path,...args);};syncBuiltinESMExports();`;

async function writePartitionFixtureHook(root:string,steps:unknown,coverage:unknown,scratchOutcome=false){
 const hook=join(root,'.local/partition-fixture-hook.mjs');await mkdir(join(root,'.local'),{recursive:true});
 await writeFile(join(root,'.local/partition-fixture-data.json'),JSON.stringify({stepsUrl:pathToFileURL(resolve('scripts/verification/steps.ts')).href,coverageUrl:pathToFileURL(resolve('scripts/verification/ci-partition-coverage.ts')).href,steps,coverage}));
 await writeFile(hook,(scratchOutcome?scratchOutcomeFixtureSource:'')+partitionFixtureHookSource);return hook;
}

test('partition fixture JSON stays data and unrelated modules retain their own exports',async()=>{
 const root=await mkdtemp(join(tmpdir(),'cv-fixture-data-'));
 try{
  const hostile=String.raw`</script><script>throw Error('fixture-data-executed')</script>"'\`;throw Error('fixture-data-executed');//`+'\u2028\u2029',steps=[{name:hostile,args:[hostile]}],coverage={source:[{id:hostile,files:[hostile]}],marker:hostile};
  const hook=await writePartitionFixtureHook(root,steps,coverage),foreign=join(root,'foreign/steps.ts');await mkdir(join(root,'foreign'));await writeFile(foreign,"export const sentinel='unrelated-module';\n");
  await writeFile(join(root,'.local/probe-input.json'),JSON.stringify({steps:pathToFileURL(resolve('scripts/verification/steps.ts')).href,coverage:pathToFileURL(resolve('scripts/verification/ci-partition-coverage.ts')).href,foreign:pathToFileURL(foreign).href}));
  const probe=join(root,'.local/probe.mjs');await writeFile(probe,String.raw`import{readFileSync,writeFileSync}from'node:fs';const input=JSON.parse(readFileSync(new URL('./probe-input.json',import.meta.url),'utf8'));const steps=await import(input.steps),coverage=await import(input.coverage),foreign=await import(input.foreign);writeFileSync(new URL('./probe-output.json',import.meta.url),JSON.stringify({steps:steps.statelessVerificationSteps,coverage:coverage.readCiPartitionCoverage(),files:coverage.ciPartitionFiles(null,'source',coverage.readCiPartitionCoverage().source[0].id),selections:coverage.ciPartitionFileSelections(null,[{id:coverage.readCiPartitionCoverage().source[0].id}]),sentinel:foreign.sentinel}));`);
  const run=spawnSync(process.execPath,['--import',pathToFileURL(resolve('node_modules/tsx/dist/loader.mjs')).href,'--import',pathToFileURL(hook).href,probe],{cwd:root,encoding:'utf8',timeout:30000,windowsHide:true});assert.equal(run.status,0,run.stderr);
  const output=JSON.parse(await readFile(join(root,'.local/probe-output.json'),'utf8'));assert.deepEqual(output.steps,steps);assert.deepEqual(output.coverage,coverage);assert.deepEqual(output.files,[hostile]);assert.deepEqual(output.selections,[[hostile]]);assert.equal(output.sentinel,'unrelated-module');assert.equal((await readFile(hook,'utf8')).includes(hostile),false,'fixture values belong only to JSON data, never executable module text');
 }finally{await rm(root,{recursive:true,force:true});}
});

test('allocated scratch cleanup refusal cannot be reported as confirmed partition cleanup',async()=>{
 const root=await mkdtemp(join(tmpdir(),'cuevo-scratch-outcome-')),scratchParent=join(root,'scratch');
 try{
  await mkdir(join(root,'scripts/verification'),{recursive:true});await mkdir(join(root,'.local'),{recursive:true});await mkdir(scratchParent);
  const file='scripts/verification/owned.test.ts';await writeFile(join(root,file),"import{test}from'node:test';test('must not start',()=>{});\n");await writeFile(join(root,'.gitignore'),'.local/\nscratch/\n');await writeFile(join(root,'.gitattributes'),'* text eol=lf\n');await writeFile(join(root,'package-lock.json'),'{}\n');await writeFile(join(root,'package.json'),'{}\n');
  const git=(args:string[])=>execFileSync('git',['-C',root,...args],{encoding:'utf8',windowsHide:true}).trim();git(['init','--quiet']);git(['add','.']);git(['-c','user.name=Fixture','-c','user.email=fixture@example.invalid','-c','commit.gpgsign=false','commit','--quiet','-m','source']);const sha=git(['rev-parse','HEAD']),steps=[{name:'cicd-fixtures',args:['--import','tsx','--test',file]}],coverage={manifestSha256:'c'.repeat(64),source:[{id:'source-native',files:[file]}],sourceCohorts:undefined};
  const hook=await writePartitionFixtureHook(root,steps,coverage,true),subject=pathToFileURL(resolve('scripts/verification/stateless-checks.ts')).href;
  const runner=join(root,'.local/scratch-runner.mjs');await writeFile(runner,`import{runStatelessPartition,runStatelessChecks}from ${JSON.stringify(subject)};import{writeFileSync}from'node:fs';const result=process.env.CUEVO_SCRATCH_OWNER==='complete'?await runStatelessChecks({repoRoot:process.cwd()}):await runStatelessPartition({repoRoot:process.cwd(),partition:'source-native'});writeFileSync('.local/outcome.json',JSON.stringify({result,diagnostic:globalThis.scratchOutcome()}));`);
  for(const owner of ['partition','complete'])for(const mode of ['remove-refuse','remove-success','allocate-refuse']){
   const run=spawnSync(process.execPath,['--import',pathToFileURL(resolve('node_modules/tsx/dist/loader.mjs')).href,'--import',pathToFileURL(hook).href,runner],{cwd:root,encoding:'utf8',env:{...process.env,TEMP:scratchParent,TMP:scratchParent,TMPDIR:scratchParent,CI:'true',GITHUB_ACTIONS:'true',GITHUB_EVENT_NAME:'pull_request',GITHUB_REPOSITORY:'owner/repo',GITHUB_SHA:sha,GITHUB_RUN_ID:'51',GITHUB_RUN_ATTEMPT:'2',GITHUB_JOB:'source-fixtures-native',CUEVO_SCRATCH_MODE:mode,CUEVO_SCRATCH_OWNER:owner}});
   assert.equal(run.status,0,run.stderr);const outcome=JSON.parse(await readFile(join(root,'.local/outcome.json'),'utf8'));
   if(owner==='partition'){assert.equal(outcome.result.status,'FAILED');assert.equal(outcome.result.exitCode,null);assert.equal(outcome.result.files[0].cases.length,0);assert.equal(outcome.result.cleanupConfirmed,mode==='remove-success','only actual guarded removal can confirm scratch cleanup');assert.equal(outcome.result.reasons.includes('STOP_UNCONFIRMED'),mode!=='remove-success');}
   else{assert.equal(outcome.result.status,mode==='remove-success'?'FAILED':'STOP_UNCONFIRMED');assert.equal(outcome.result.groups[0].status,mode==='remove-success'?'PROCESS_ERROR':'STOP_UNCONFIRMED');assert.equal(outcome.result.groups[0].exitCode,null);assert.equal(outcome.result.groups[0].summary,null);}
   assert.equal(JSON.stringify(outcome.result).includes('private-scratch-canary'),false);
   if(mode==='remove-refuse'){assert.equal(outcome.diagnostic.removals,1);const allocated=resolve(outcome.diagnostic.allocated);assert.equal(resolve(allocated,'..'),resolve(scratchParent));assert.match(relative(scratchParent,allocated),/^cv-[a-zA-Z0-9]+$/);assert.equal((await lstat(allocated)).isDirectory(),true);await rm(allocated,{recursive:true,force:true});}
   if(mode==='remove-success'){assert.equal(outcome.diagnostic.removals,1);await assert.rejects(lstat(outcome.diagnostic.allocated),{code:'ENOENT'});}
   if(mode==='allocate-refuse'){assert.equal(outcome.diagnostic.allocated,null);assert.equal(outcome.diagnostic.removals,0);}
  }
 }finally{await rm(root,{recursive:true,force:true});}
});

