   return row.ordinal===21?`test(${JSON.stringify(titles.get(row.titleSha256))},async t=>{${body}for(const mode of ['COMMIT_REPLY_LOST','READBACK_MISMATCH','LEASE_LOST_AFTER_CREATE'] as const)await t.test(mode,async()=>{appendFileSync('.local/children.jsonl',mode+'\\n');});});`:`test(${JSON.stringify(titles.get(row.titleSha256))},async t=>{${body}});`;
