  const git=(args:string[])=>execFileSync('git',['-C',root,...args],{encoding:'utf8',windowsHide:true}).trim();git(['init','--quiet']);git(['add','.']);git(['-c','user.name=Fixture','-c','user.email=fixture@example.invalid','-c','commit.gpgsign=false','commit','--quiet','-m','closed cohort fixture']);const sha=git(['rev-parse','HEAD']);
  const coverage={source:[{id:'source-contracts',files:[cohorts.SOURCE_TEST_COHORT_FILE,ordinary]}],sourceCohorts:{version:1,file:plan.file.path,policySha256:plan.policySha256},manifestSha256:'c'.repeat(64)},steps=[{name:'migration-replay-rules',args:['--import','tsx','--test',cohorts.SOURCE_TEST_COHORT_FILE,ordinary]}],hook=await writePartitionFixtureHook(root,steps,coverage);
  const script=join(root,'.local/run.mjs'),subject=pathToFileURL(join(actualRoot,'scripts/verification/stateless-checks.ts')).href;
