   const result=spawnSync(process.execPath,['--import',pathToFileURL(join(actualRoot,'node_modules/tsx/dist/loader.mjs')).href,'--import',pathToFileURL(hook).href,script],{cwd:root,encoding:'utf8',timeout:30000,maxBuffer:4*1024*1024,windowsHide:true,env:{...process.env,CI:'true',GITHUB_ACTIONS:'true',GITHUB_EVENT_NAME:'pull_request',GITHUB_REPOSITORY:'owner/repo',GITHUB_SHA:sha,GITHUB_RUN_ID:'51',GITHUB_RUN_ATTEMPT:'1',GITHUB_JOB:'source-fixtures-contracts',CUEVO_COHORT_TEST_MODE:mode}});
   const receipt=JSON.parse(await readFile(join(root,'.local/result.json'),'utf8'));assert.equal(receipt.cleanupConfirmed,true,mode);assert.equal((result.stdout+result.stderr+JSON.stringify(receipt)).includes('private-cohort-canary'),false);
   if(mode==='pass'){assert.equal(result.status,0,result.stderr);assert.equal(receipt.status,'PASSED');const file=receipt.files.find((row:{path:string})=>row.path===plan.file.path);assert.equal(file.cases.length,33);assert.equal(file.cohortEvidence.receipts.length,5);const identity={sourceSha:receipt.identity.sourceSha,treeSha:receipt.identity.treeSha,sourceLockSha256:receipt.identity.sourceLockSha256,nodeVersion:receipt.identity.nodeVersion,runId:'51',runAttempt:1,scope:'source-contracts',partitionSha256:coverage.manifestSha256};assert.equal(review.canonicalReleaseExecutionJson(cohorts.validateSourceTestCohortEvidence(plan,file.cohortEvidence,identity)),review.canonicalReleaseExecutionJson(file));const executed=(await readFile(join(root,'.local/executed.jsonl'),'utf8')).trim().split('\n').map(row=>JSON.parse(row));assert.equal(executed.length,30);assert.equal(new Set(executed.map(row=>row.ordinal)).size,30);assert.equal(new Set(executed.map(row=>row.temp)).size,5);for(const scratch of new Set<string>(executed.map(row=>row.temp)))await assert.rejects(lstat(scratch));assert.equal((await readFile(join(root,'.local/children.jsonl'),'utf8')).trim().split('\n').length,3);assert.equal((await readFile(join(root,'.local/ordinary.jsonl'),'utf8')).trim().split('\n').length,1);}
