  await writeFile(join(root,'.local/cohort-run-input.json'),JSON.stringify({subject,repoRoot:root,id:producerId}));
  await writeFile(script,fixedProducerFixtureSource);
  const runProducer=(mode:string)=>spawnSync(process.execPath,['--import',pathToFileURL(join(actualRoot,'node_modules/tsx/dist/loader.mjs')).href,'--import',pathToFileURL(hook).href,script],{cwd:root,encoding:'utf8',timeout:30000,maxBuffer:4*1024*1024,windowsHide:true,env:{...process.env,CI:'true',GITHUB_ACTIONS:'true',GITHUB_EVENT_NAME:'pull_request',GITHUB_REPOSITORY:'owner/repo',GITHUB_SHA:sha,GITHUB_RUN_ID:'51',GITHUB_RUN_ATTEMPT:'1',GITHUB_JOB:'source-cohort-'+producerId,GITHUB_WORKSPACE:root,CUEVO_COHORT_TEST_MODE:mode}});
